import{_ as t}from"./chunks/ark_sam_gps.DmY9m4RH.js";import{_ as e,c as r,o,al as i}from"./chunks/framework.D8UyiDWg.js";const S=JSON.parse('{"title":"ARK SAM GPS","description":"","frontmatter":{},"headers":[],"relativePath":"uk/gps_compass/ark_sam_gps.md","filePath":"uk/gps_compass/ark_sam_gps.md"}'),n={name:"uk/gps_compass/ark_sam_gps.md"};function l(s,a,d,h,c,p){return o(),r("div",null,a[0]||(a[0]=[i('<h1 id="ark-sam-gps" tabindex="-1">ARK SAM GPS <a class="header-anchor" href="#ark-sam-gps" aria-label="Permalink to &quot;ARK SAM GPS&quot;">​</a></h1><p><a href="https://arkelectron.gitbook.io/ark-documentation/gps/ark-sam-gps%3E" target="_blank" rel="noreferrer">ARK SAM GPS</a> is a made in the USA and NDAA-compliant <a href="./../gps_compass/">GNSS/GPS</a> u-blox SAM-M10Q GPS and industrial magnetometer.</p><p><img src="'+t+'" alt="ARK SAM GPS"></p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>Замовте цей модуль з:</p><ul><li><a href="https://arkelectron.com/product/ark-sam-gps/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="характеристики-обладнання" tabindex="-1">Характеристики обладнання <a class="header-anchor" href="#характеристики-обладнання" aria-label="Permalink to &quot;Характеристики обладнання&quot;">​</a></h2><ul><li><a href="https://github.com/ARK-Electronics/ARK_SAM_GPS/tree/main" target="_blank" rel="noreferrer">Open Source Schematic and BOM</a></li><li>Датчики <ul><li><a href="https://www.u-blox.com/en/product/sam-m10q-module" target="_blank" rel="noreferrer">u-blox SAM-M10Q</a><ul><li>Less than 38 mW power consumption without compromising GNSS performance</li><li>Maximum position availability with 4 concurrent GNSS reception</li><li>Просунуте виявлення підробки сигналу та перешкод</li></ul></li><li><a href="https://www.st.com/en/mems-and-sensors/iis2mdc.html" target="_blank" rel="noreferrer">ST IIS2MDC Magnetometer</a></li></ul></li><li>Pixhawk Standard UART/I2C Connector (6 Pin JST SH)</li><li>Вимоги до живлення <ul><li>5V</li><li>15mA Average</li><li>20mA Max</li></ul></li><li>LED індикатори <ul><li>GPS Fix</li></ul></li><li>USA Built</li><li>NDAA Compliant</li><li>6 Pin Pixhawk Standard UART/I2C Cable</li></ul><h2 id="налаштування-обладнання" tabindex="-1">Налаштування обладнання <a class="header-anchor" href="#налаштування-обладнання" aria-label="Permalink to &quot;Налаштування обладнання&quot;">​</a></h2><p>The module comes with a Pixhawk-standard 6pin connector that will plug into the <code>GPS2</code> port on recent Pixhawk flight controllers. It should be mounted front facing, as far away from the flight controller and other electronics as possible.</p><p>For more information see <a href="./../gps_compass/#mounting-the-gnss-compass">Mounting the GNSS/Compass</a> and <a href="./../gps_compass/#hardware-setup">Hardware Setup</a>.</p><h2 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h2><p>The module should be plug-n-play when used with the <code>GPS2</code> port on most flight controllers.</p><p><a href="./../gps_compass/#secondary-gps-configuration-uart">Secondary GPS Configuration (UART)</a> explains how you can configure the port if the GPS is not detected (note, that the configuration is the same, even if you are using GPS 2 as the primary compass).</p><h2 id="схема-розташування-виводів" tabindex="-1">Схема розташування виводів <a class="header-anchor" href="#схема-розташування-виводів" aria-label="Permalink to &quot;Схема розташування виводів&quot;">​</a></h2><h3 id="pixhawk-standard-uart-i2c-connector-6-pin-jst-sh" tabindex="-1">Pixhawk Standard UART/I2C Connector - 6 Pin JST-SH <a class="header-anchor" href="#pixhawk-standard-uart-i2c-connector-6-pin-jst-sh" aria-label="Permalink to &quot;Pixhawk Standard UART/I2C Connector - 6 Pin JST-SH&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin Number</th><th>Signal Name</th><th>Напруга</th></tr></thead><tbody><tr><td>1</td><td>5V</td><td>5.0V</td></tr><tr><td>2</td><td>RX</td><td>3.3V</td></tr><tr><td>3</td><td>TX</td><td>3.3V</td></tr><tr><td>4</td><td>SCL</td><td>3.3V</td></tr><tr><td>5</td><td>SDA</td><td>3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="https://arkelectron.gitbook.io/ark-documentation/gps/ark-sam-gps" target="_blank" rel="noreferrer">ARK SAM GPS Documentation</a> (ARK Docs)</li></ul>',19)]))}const g=e(n,[["render",l]]);export{S as __pageData,g as default};
